import{_ as a,o as s,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"28. Function Pointers and Callbacks","description":"The Little Book of C — 28. Function Pointers and Callbacks","frontmatter":{"title":"28. Function Pointers and Callbacks","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working with Memory"],"description":"The Little Book of C — 28. Function Pointers and Callbacks","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":28,"sidebarWeight":28,"lang":"en-US","alternateEn":"/posts/c教程/en-US/03-Working with Memory/028-Function Pointers and Callbacks","alternateZh":"/posts/c教程/zh-CN/03-内存/028-Function Pointers and Callbacks"},"headers":[],"relativePath":"posts/c教程/en-US/03-Working with Memory/028-Function Pointers and Callbacks.md","filePath":"posts/c教程/en-US/03-Working with Memory/028-Function Pointers and Callbacks.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/03-Working with Memory/028-Function Pointers and Callbacks.md"};function p(l,n,o,c,r,d){return s(),t("div",null,[...n[0]||(n[0]=[e(`<p>[中文版本](/posts/c教程/zh-CN/03-内存/028-Function Pointers and Callbacks)</p><p>Functions in C are values too, they live in memory and have addresses just like variables. A function pointer is a pointer that stores the address of a function, allowing you to call that function indirectly. This idea powers callbacks, event systems, custom sorters, and plug-in architectures in C.</p><h4 id="what-is-a-function-pointer" tabindex="-1">What Is a Function Pointer? <a class="header-anchor" href="#what-is-a-function-pointer" aria-label="Permalink to &quot;What Is a Function Pointer?&quot;">​</a></h4><p>Just like<code>int *</code> points to an integer, a function pointer points to a function.</p><p>Syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>return_type (*pointer_name)(parameter_types);</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int (*func_ptr)(int, int) = add;</span></span></code></pre></div><p>Now you can call the function through the pointer:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int result = func_ptr(2, 3); // same as add(2, 3)</span></span></code></pre></div><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Here’s a complete example showing how to declare, assign, and call function pointers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int sub(int a, int b) { return a - b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span>
<span class="line"><span>void operate(int x, int y, int (*op)(int, int)) {</span></span>
<span class="line"><span>    printf(&quot;Result: %d\\n&quot;, op(x, y)); // call through pointer</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int (*f)(int, int); // declaration</span></span>
<span class="line"><span>    f = add;</span></span>
<span class="line"><span>    printf(&quot;Add via pointer: %d\\n&quot;, f(5, 3));</span></span>
<span class="line"><span>    f = sub;</span></span>
<span class="line"><span>    printf(&quot;Subtract via pointer: %d\\n&quot;, f(5, 3));</span></span>
<span class="line"><span>    printf(&quot;\\nUsing callback function:\\n&quot;);</span></span>
<span class="line"><span>    operate(4, 6, mul); // pass function pointer as argument</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc func_pointer_demo.c -o func_pointer_demo</span></span>
<span class="line"><span>./func_pointer_demo</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add via pointer: 8</span></span>
<span class="line"><span>Subtract via pointer: 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Using callback function:</span></span>
<span class="line"><span>Result: 24</span></span></code></pre></div><h4 id="function-pointers-in-arrays" tabindex="-1">Function Pointers in Arrays <a class="header-anchor" href="#function-pointers-in-arrays" aria-label="Permalink to &quot;Function Pointers in Arrays&quot;">​</a></h4><p>You can also store multiple function pointers in an array, useful for building tables of operations.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int (*ops[3])(int, int) = {add, sub, mul};</span></span>
<span class="line"><span>for (int i = 0; i &lt; 3; i++)</span></span>
<span class="line"><span>    printf(&quot;ops[%d](4, 2) = %d\\n&quot;, i, ops[i](4, 2));</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ops[0](4, 2) = 6</span></span>
<span class="line"><span>ops[1](4, 2) = 2</span></span>
<span class="line"><span>ops[2](4, 2) = 8</span></span></code></pre></div><p>This pattern underlies dispatch tables, interpreters, and virtual function systems in C.</p><h4 id="callbacks" tabindex="-1">Callbacks <a class="header-anchor" href="#callbacks" aria-label="Permalink to &quot;Callbacks&quot;">​</a></h4><p>A callback is a function you pass as an argument to another function, letting the callee “call back” into user code. This pattern is essential in event-driven and modular designs.</p><p>Example: a simple iterator that accepts a callback</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void for_each(int *arr, int n, void (*callback)(int)) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>        callback(arr[i]);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void print_square(int x) {</span></span>
<span class="line"><span>    printf(&quot;%d^2 = %d\\n&quot;, x, x * x);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int nums[] = {1, 2, 3, 4, 5};</span></span>
<span class="line"><span>    for_each(nums, 5, print_square); // pass callback</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1^2 = 1</span></span>
<span class="line"><span>2^2 = 4</span></span>
<span class="line"><span>3^2 = 9</span></span>
<span class="line"><span>4^2 = 16</span></span>
<span class="line"><span>5^2 = 25</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Function pointers let you:</p><ul><li>Select behavior at runtime (dynamic dispatch).</li><li>Pass logic into libraries without recompiling them.</li><li>Build frameworks, event handlers, interpreters, and plug-ins.</li><li>Replace huge switch-case structures with elegant dispatch tables.</li></ul><p>They are also how C implements:</p><ul><li><code>qsort()</code> and<code>bsearch()</code> comparison functions,</li><li>signal handlers (<code>signal(SIGINT, handler)</code>), and</li><li>system callbacks in GUIs or kernels.</li></ul><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write three arithmetic functions and store them in an array of function pointers.</li><li>Build a<code>calculate(a, b, char op)</code> function that picks the right function pointer based on<code>op</code>.</li><li>Implement a callback-style loop that calls a user-defined function for each array element.</li><li>Pass a function pointer to<code>qsort()</code> from<code>&lt;stdlib.h&gt;</code> to sort integers in descending order.</li><li>Write a small menu system that calls the right function based on user choice.</li></ol><p>Function pointers and callbacks give your programs flexibility and abstraction without sacrificing speed. They’re how C achieves dynamic behavior, the bridge between data and executable logic.</p>`,37)])])}const b=a(i,[["render",p]]);export{h as __pageData,b as default};
